function formatDeadline(contract){const deadline=(contract?.external_deadline_refs||[]).find(item=>item.source==='exam_calendar');if(!deadline)return {label:'尚未设置',value:''};const at=new Date(deadline.due_at);return {label:(deadline.title||'项目截止')+' · '+(Number.isNaN(at.getTime())?deadline.due_at:at.toLocaleDateString()),value:Number.isNaN(at.getTime())?'':at.toISOString().slice(0,10)}}
function renderPlanDashboard(workspace=currentWorkspace,project=activeProjectRecord,reviews=projectReviews){const title=$('plan-project-title'),description=$('plan-project-description'),deadline=$('plan-project-deadline'),stage=$('plan-current-stage'),count=$('plan-review-count'),progress=$('plan-total-progress'),progressText=$('plan-progress-text'),milestonesBox=$('milestone-track'),today=$('today-tasks');if(!project){title.textContent='请选择学习项目';description.textContent='项目用于组织目标、计划、任务和学习证据。';deadline.textContent='尚未设置';stage.textContent='尚未设置里程碑';count.textContent='0 项';progress.max=1;progress.value=0;progressText.textContent='0 / 0 项任务完成';milestonesBox.replaceChildren(text('p','请先创建项目。'));today.replaceChildren(text('p','暂无项目任务或到期复习。'));return}const content=project.content||{},tasks=content.tasks||[],milestones=content.milestones||[],done=tasks.filter(task=>task.status==='done'||task.status==='completed').length,current=milestones.find(item=>item.status!=='done')||milestones.at(-1);title.textContent=content.title;description.textContent=content.description||'尚未填写项目说明。';const date=formatDeadline(workspace?.contract);deadline.textContent=date.label;stage.textContent=current?current.title+(current.status==='done'?' · 已完成':' · 进行中'):'尚未设置里程碑';count.textContent=(reviews?.length||0)+' 项';progress.max=tasks.length||1;progress.value=done;progressText.textContent=done+' / '+tasks.length+' 项任务完成';milestonesBox.replaceChildren();if(!milestones.length)milestonesBox.append(text('p','尚未设置里程碑；可在“编辑项目”中添加。'));for(const milestone of milestones){const item=document.createElement('div');item.className='milestone '+milestone.status;item.append(text('strong',milestone.status==='done'?'✓ ':milestone.status==='doing'?'● ':'○ '),text('span',milestone.title));milestonesBox.append(item)}today.replaceChildren();const launch=(task,prefix='待办')=>{const item=document.createElement('div');item.className='row';const label=text('span',prefix+' · '+task.title);const button=text('button','开始任务');button.onclick=()=>run(()=>startProjectTask(task))();item.append(label,button);today.append(item)};const pending=tasks.filter(task=>task.status!=='done'&&task.status!=='completed');for(const task of pending.slice(0,5))launch(task,task.status==='doing'?'进行中':'待办');for(const task of (reviews||[]).slice(0,3)){const linked=tasks.find(item=>item.task_id===task.task_id)||{...task,title:'无提示复习 · '+task.kc_id,type:'review',completion_rule:'verified_submission',created_from:'system'};launch(linked,'复习');}if(!today.childElementCount)today.append(text('p','暂无项目任务或到期复习。'));$('plan-proposal-hint').textContent=workspace?.contract?'建议依据当前项目的有效证据、待复习任务和截止日期生成；不会自动改写已签署计划。':'先建立目标与成功标准，再生成路径建议。'}
