function renderStudyContext(){const task=activeStudyTask,content=activeProjectRecord?.content||{},milestone=(content.milestones||[]).find(item=>item.milestone_id===task?.milestone_id);$('study-context-title').textContent=task?task.title:'自由探索';$('study-context-project').textContent=activeProjectId?'当前项目：'+(content.title||'未命名项目'):'请先创建并选择学习项目。';$('study-context-goal').textContent=currentWorkspace?.contract?.goal_statement?.text||'尚未设置目标';$('study-context-milestone').textContent=task?(milestone?.title||'未关联里程碑'):'自由探索';$('study-context-source').textContent=task?'项目任务 · '+(taskTypeLabels[task.type]||task.type)+' · '+(task.created_from==='system'?'系统提醒':task.created_from==='plan'?'计划生成':'学生创建'):'自由提问／自由探索 · 不会自动完成计划任务';$('reflection-flow').hidden=task?.type!=='reflection';$('assessment-flow').hidden=task?.type==='reflection';$('start-task-session').hidden=!task;$('session-mode-hint').textContent=task?'当前聊天可关联到此任务；只有提交符合完成规则的作答，或你手动确认反思，才会改变任务状态。':'自由提问／自由探索不会自动完成计划任务。'}
