async function startProjectTask(task){if(!activeProjectId||task.project_id&&task.project_id!==activeProjectId)throw Error('任务不属于当前项目');activeStudyTask=task;review=null;submission=null;renderStudyContext();show('study');if(task.type==='reflection'){ $('reflection-note').value='';$('task-stem').textContent='请完成一段学习反思，再由你确认完成。';notice('已进入反思任务；不会因为打开页面或发送消息而自动完成');return }if(task.type==='review'){const due=projectReviews.find(item=>item.task_id===task.task_id);if(!due){show('reviews');throw Error('该复习任务当前尚未到期，或已被新的复习任务替代。')}const asset=assets.find(item=>item.kind==='delayed'&&item.kc_refs.some(ref=>ref.asset_id===due.kc_id));if(!asset)throw Error('当前知识点缺少复习题目');$('target').value=due.kc_id;if(![...$('assessment').options].some(option=>option.value===asset.ref.asset_id)){$('assessment').append(Object.assign(text('option',asset.ref.asset_id+' · 到期复习'),{value:asset.ref.asset_id}))}$('assessment').value=asset.ref.asset_id;chooseTask();review=due;$('assisted').checked=false;notice('项目复习任务已就绪');return}if(task.type==='assessment'&&/初诊/.test(task.title)){await $('diagnose').onclick();return}selectTaskAsset(task);notice('已从当前项目任务启动；本次作答只会关联到该任务。')}
