async function activateProject(projectId,force=false){if(projectId===activeProjectId&&!force)return;privacyEpoch++;for(const request of pendingRequests)request.abort();activeProjectId=projectId;activeStudyTask=null;taskEpoch++;sessionId=null;review=null;submission=null;sessionSubmission=null;path=null;planVersion=null;taskDelivery=null;deliveryReady=null;$('chat').replaceChildren(text('p','当前项目暂无会话'));$('session-recovery-id').value='';$('verdict').textContent='';$('collaboration-results').replaceChildren();$('teach-results').replaceChildren();$('memory-result').replaceChildren(text('p','暂无项目记忆摘要'));$('project-switch').value=projectId||'';changeTarget();await Promise.all([restorePlanWorkspace(),loadReviews(),loadEvidence(),loadCollaborationEvidence(),loadProjectSessions()]);await updateOverview();renderStudyContext();notice('已切换当前学习项目')}
tabs.forEach((button,index)=>{button.onclick=()=>activateTab(button);button.onkeydown=event=>{let next;if(event.key==='ArrowRight')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft')next=(index-1+tabs.length)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();activateTab(tabs[next]);tabs[next].focus()}});
