$('submit').onclick=run(async()=>{const a=selected(),epoch=taskEpoch;if(!a||(!$('answer').value.trim()&&$('self-report').value==='answered'))throw Error('请填写作答');const qualitative=a.kind==='explanation';if(!qualitative){await deliveryReady;if(epoch!==taskEpoch||!taskDelivery)throw Error('请重新选择任务以获取发题凭据');if(!submission&&taskDelivery.consumed){taskDelivery=await api('/api/learning/assessment/'+learner+'/issue',projectBody({assessment_id:a.ref.asset_id,assessment_version:a.ref.version,issuance_id:crypto.randomUUID()}));if(epoch!==taskEpoch)return}}if(!submission){const assist=$('assisted').checked;submission=projectBody({assessment_id:a.ref.asset_id,assessment_version:a.ref.version,attempt_id:crypto.randomUUID(),hint_level:assist?1:0,assistance_mode:assist?'hint':'none',answer_exposed:false,...(qualitative?{content:$('answer').value}:{answer:$('answer').value,occurred_at:new Date().toISOString(),self_report:$('self-report').value,delivery_ref:taskDelivery.delivery_ref}),...(activeStudyTask?{task_id:activeStudyTask.task_id}:{})});if(review)submission.task_id=review.task_id}const result=await api(qualitative?'/api/learning/qualitative/'+learner+'/artifacts':'/api/learning/'+(review?'reviews':'assessment')+'/'+learner+'/submit',submission);if(!qualitative)taskDelivery.consumed=true;$('verdict').textContent=qualitative?'作品已保存，待匹配 Rubric 的教师评审':labels[result.verdict_status]||result.verdict_status;notice(qualitative?'作品与待验证证据已保存，不计入掌握更新':result.completed_task_ids?.length?'作答、证据与当前项目任务已更新':'作答与学习证据已保存；任务尚需满足完成规则');await updateOverview();if(review)await loadReviews()});
$('complete-reflection-task').onclick=run(async()=>{if(!activeStudyTask||activeStudyTask.type!=='reflection')throw Error('请先从项目任务启动一项反思');if(!$('reflection-note').value.trim())throw Error('请先写下你的学习反思');const result=await api('/api/learning/projects/'+learner+'/tasks/'+encodeURIComponent(activeStudyTask.task_id)+'/complete',projectBody({}));if(!result.completed_task_ids.length)throw Error('该反思任务已经完成或无法更新');$('verdict').textContent='反思已由你确认完成';await updateOverview();notice('反思任务已完成；记录只属于当前项目')});
$('appeal-evidence').oninput=$('appeal-reason').oninput=()=>appealSubmission=null;
$('submit-appeal').onclick=run(async()=>{if(!$('appeal-evidence').value.trim()||!$('appeal-reason').value.trim())throw Error('请填写证据编号和申诉理由');if(!appealSubmission)appealSubmission={evidence_id:$('appeal-evidence').value.trim(),reason:$('appeal-reason').value.trim(),appeal_id:'appeal:'+crypto.randomUUID()};const result=await api('/api/learning/appeals/'+learner,appealSubmission);$('appeal-result').replaceChildren(text('p','申诉已提交 · '+result.appeal_id));notice('申诉已保存，等待人工复核')});
function goalCriteria(){return $('goal-criteria').value.split(/\n/).map(value=>value.trim()).filter(Boolean)}
function goalDeadline(){const value=$('goal-deadline').value;return value?{deadline_title:'项目截止日期',deadline_at:new Date(value+'T23:59:59').toISOString()}:{}}
$('save-goal').onclick=run(async()=>{if(!activeProjectId)throw Error('请先创建并选择学习项目');const goal=$('goal').value.trim();if(!goal)throw Error('请填写学习目标');const existed=!!currentWorkspace?.contract;const body=projectBody({learner_id:learner,goal_text:goal,success_criteria:goalCriteria(),...goalDeadline()});if(currentWorkspace?.contract)await api('/api/contracts/'+encodeURIComponent(currentWorkspace.contract.goal_contract_id),body,'PUT');else await api('/api/contracts',body);await restorePlanWorkspace();await updateOverview();notice(existed?'目标与成功标准已更新，请重新审阅计划。':'学习目标已建立')});
function dateToPlanValue(value){return value?new Date(value).toISOString().slice(0,10):''}
function planDeadlineValue(){const value=$('plan-deadline').value;return value?new Date(value+'T23:59:59').toISOString():null}
function currentProjectPlan(){return activeProjectRecord?.content?structuredClone(activeProjectRecord.content):null}
function editedPlanContent(content,projectPlan=content.project_plan||currentProjectPlan()){return {...content,cadence:$('cadence').value.trim(),learner_notes:$('plan-notes').value.trim(),deadline_at:planDeadlineValue(),...(projectPlan?{project_plan:projectPlan}:{})}}
$('get-path').onclick=run(async()=>{if(!activeProjectId)throw Error('请先创建并选择学习项目');path=await api(projectUrl('/api/path/recommend?learner_id='+encodeURIComponent(learner)));const proposal=await api('/api/path/propose',projectBody({learner_id:learner,path}));await restorePlanWorkspace();$('saved-plan').value=proposal.version_id;restorePlanSelection();notice('系统建议已保存；请先审阅、采纳或拒绝')});
$('draft-plan').onclick=run(async()=>{const saved=savedPlans.find(plan=>plan.version_id===planVersion&&plan.status==='proposed');if(!saved)throw Error('请先生成并选择一份系统建议');const accepted=await api('/api/learning/plans/'+learner+'/'+encodeURIComponent(saved.version_id)+'/accept',projectBody({}));await loadProjects();await restorePlanWorkspace();$('saved-plan').value=accepted.version_id;restorePlanSelection();await updateOverview();notice('已从系统建议建立你的草案；尚未签署前不会替代当前计划')});
$('modify-plan').onclick=run(async()=>{if(!planVersion)throw Error('请先选择要调整的草案或已签署计划');const current=await api(projectUrl('/api/plans/'+encodeURIComponent(planVersion)+'?learner_id='+encodeURIComponent(learner)));const reason=$('plan-notes').value.trim();if(!reason)throw Error('请说明这次调整的原因');const revised=await api('/api/plans/'+encodeURIComponent(planVersion)+'/modify',projectBody({learner_id:learner,content:editedPlanContent(current.content),reason}));await restorePlanWorkspace();$('saved-plan').value=revised.version_id;restorePlanSelection();notice('调整已保存为新的未签署草案；当前已签署计划仍保持生效')});
$('sign-plan').onclick=run(async()=>{await api('/api/plans/'+encodeURIComponent(planVersion)+'/sign',projectBody({learner_id:learner}));await loadProjects();await restorePlanWorkspace();await updateOverview();notice('计划已由你签署并生效；后续调整会创建新版本')});
$('reject-plan').onclick=run(async()=>{const reason=$('reject-reason').value.trim();if(!reason)throw Error('请填写拒绝原因；它只会作为后续建议的参考');await api('/api/plans/'+encodeURIComponent(planVersion)+'/reject',projectBody({learner_id:learner,reason}));$('reject-reason').value='';await restorePlanWorkspace();notice('拒绝原因已记录，不会用于评价你')});
function addChat(who,message){const p=text('p',who+'：'+message);p.className=who==='我'||who==='我的作答'?'message-self':'message-companion';$('chat').append(p);$('chat').scrollTop=$('chat').scrollHeight}
function renderPlanHistory(history=[]){const box=$('plan-history');box.replaceChildren();if(!history.length){box.append(text('p','暂无计划版本'));return}const names={proposed:'系统建议',draft:'我的草案',confirmed:'已签署',rejected:'已拒绝',superseded:'已替代'};for(const plan of history){const item=document.createElement('button');item.type='button';item.className='plan-history-item '+plan.status;item.textContent=(names[plan.status]||plan.status)+' · '+plan.version_id.slice(0,8)+(plan.change_reason?' · '+plan.change_reason:'');item.onclick=()=>{$('saved-plan').value=plan.version_id;restorePlanSelection()};box.append(item)}}
function restorePlanSelection(){const plan=savedPlans.find(item=>item.version_id===$('saved-plan').value)||savedPlans[0];if(plan&&$('saved-plan').value!==plan.version_id)$('saved-plan').value=plan.version_id;planVersion=plan?.version_id||null;planLocked=!plan||plan.status!=='draft';$('sign-plan').disabled=!plan||plan.status!=='draft';$('reject-plan').disabled=!plan||!['proposed','draft'].includes(plan.status);$('modify-plan').disabled=!plan||!['draft','confirmed'].includes(plan.status);$('plan-status').textContent=!plan?'暂无版本':({draft:'草案 · 等待签署',proposed:'系统建议 · 等待决定',confirmed:'已签署 · 当前生效',rejected:'已拒绝',superseded:'历史版本'}[plan.status]||plan.status);path=plan?.content.path||null;$('draft-plan').disabled=!plan||plan.status!=='proposed';if(path)renderPath(path);else $('path').replaceChildren(text('p','当前版本没有路径建议'));if(!plan){$('plan-detail').replaceChildren();return}renderPlan(plan.status,plan.diff||{},plan.change_reason||'');$('cadence').value=plan.content.cadence||'';$('plan-notes').value=plan.content.learner_notes||'';$('plan-deadline').value=dateToPlanValue(plan.content.deadline_at)||formatDeadline(currentWorkspace?.contract).value}
async function restorePlanWorkspace(){const workspace=await api(projectUrl('/api/learning/plans/'+learner+'/workspace'));currentWorkspace=workspace;savedPlans=workspace.history||[...workspace.drafts,...workspace.proposals,...(workspace.active?[workspace.active]:[])];$('goal').value=workspace.contract?.goal_statement?.text||'';$('goal-criteria').value=(workspace.contract?.success_criteria||[]).map(item=>item.description||((item.kind==='post_test'?'独立完成后测，正确率达到 ':'完成标准 ')+Math.round((item.threshold||0)*100)+'%')).join('\n');$('goal-deadline').value=formatDeadline(workspace.contract).value;$('save-goal').textContent=workspace.contract?'更新目标':'建立目标';$('workspace-summary').textContent=workspace.contract?'已保存目标 · 当前有效计划 '+(workspace.active?'1':'0')+' · 待签署草案 '+workspace.drafts.length+' · 待决定建议 '+workspace.proposals.length:'暂无已保存目标';$('saved-plan').replaceChildren();if(!savedPlans.length){const option=text('option','暂无已保存计划');option.value='';$('saved-plan').append(option)}else for(const plan of savedPlans){const option=text('option',({draft:'草案',confirmed:'已签署',proposed:'系统建议',rejected:'已拒绝',superseded:'历史'}[plan.status]||plan.status)+' · '+plan.version_id.slice(0,12));option.value=plan.version_id;$('saved-plan').append(option)}renderPlanHistory(savedPlans);restorePlanSelection();renderPlanDashboard(workspace,activeProjectRecord,projectReviews)}
$('saved-plan').onchange=restorePlanSelection;$('restore-plans').onclick=run(restorePlanWorkspace);
function editProject(project){projectEdit=project;projectTasks=(project?.content.tasks||[]).map(task=>({...task}));projectMilestones=(project?.content.milestones||[]).map(milestone=>({...milestone}));$('project-title').value=project?.content.title||'';$('project-description').value=project?.content.description||'';for(const [id,key] of [['project-evidence-refs','evidence_refs'],['project-session-refs','session_refs'],['project-source-refs','source_refs']])$(id).value=(project?.content[key]||[]).join('\n');renderProjectMilestones();renderProjectTasks();if(project)$('project-title').focus()}
async function loadProjects(){await updateOverview()}
function renderProjectMilestones(){const box=$('project-milestone-editor');box.replaceChildren();for(const milestone of projectMilestones){const row=document.createElement('div');row.className='row';const title=document.createElement('input');title.value=milestone.title;title.setAttribute('aria-label','里程碑名称');title.onchange=()=>milestone.title=title.value;const status=document.createElement('select');status.setAttribute('aria-label','里程碑状态');for(const [value,label] of [['todo','待开始'],['doing','进行中'],['done','已完成']]){const option=text('option',label);option.value=value;status.append(option)}status.value=milestone.status;status.onchange=()=>milestone.status=status.value;const remove=text('button','移除');remove.onclick=()=>{projectMilestones=projectMilestones.filter(item=>item.milestone_id!==milestone.milestone_id);projectTasks.forEach(task=>{if(task.milestone_id===milestone.milestone_id)task.milestone_id=null});renderProjectMilestones();renderProjectTasks()};row.append(title,status,remove);box.append(row)}}
function renderProjectTasks(){const box=$('project-task-editor');box.replaceChildren();for(const task of projectTasks){const row=document.createElement('div');row.className='row';const title=document.createElement('input');title.value=task.title;title.setAttribute('aria-label','任务名称');title.onchange=()=>task.title=title.value;const type=document.createElement('select');type.setAttribute('aria-label','任务类型');for(const [value,label] of Object.entries(taskTypeLabels)){const option=text('option',label);option.value=value;type.append(option)}type.value=task.type||'manual';type.onchange=()=>{task.type=type.value;task.completion_rule=taskRuleForType[task.type];if(task.completion_rule!=='manual'&&task.status==='done')task.status='todo';renderProjectTasks()};const status=document.createElement('select');status.setAttribute('aria-label','任务状态');for(const [value,label] of [['todo','待办'],['doing','进行中'],['done','已完成'],['skipped','已跳过']]){const option=text('option',label);option.value=value;status.append(option)}status.value=task.status||'todo';status.disabled=(task.completion_rule||taskRuleForType[task.type]||'manual')!=='manual';status.title=status.disabled?'此任务会在满足完成规则后自动完成':'手动任务由学习者自行更新状态';status.onchange=()=>task.status=status.value;const due=document.createElement('input');due.type='date';due.setAttribute('aria-label','截止日期');due.value=task.due_at?new Date(task.due_at).toISOString().slice(0,10):'';due.onchange=()=>task.due_at=due.value?new Date(due.value+'T23:59:59').toISOString():null;const assessment=document.createElement('select');assessment.setAttribute('aria-label','关联练习或测评');const blankAssessment=text('option','未关联练习或测评');blankAssessment.value='';assessment.append(blankAssessment);for(const item of assets){const option=text('option',item.ref.asset_id+' · '+(labels[item.kind]||item.kind));option.value=item.ref.asset_id+'@'+item.ref.version;assessment.append(option)}assessment.value=task.assessment_ref||'';assessment.onchange=()=>task.assessment_ref=assessment.value||null;const rule=document.createElement('select');rule.setAttribute('aria-label','完成规则');for(const [value,label] of [['manual','手动完成'],['verified_submission','验证通过后完成'],['assessment_finalized','交卷并处理结果后完成'],['teacher_review','教师确认后完成']]){const option=text('option',label);option.value=value;rule.append(option)}rule.value=task.completion_rule||taskRuleForType[task.type]||'manual';rule.disabled=task.created_from==='plan'||task.created_from==='system';rule.title=rule.disabled?'计划或系统任务的完成规则不可手动改写':'选择任务完成规则';rule.onchange=()=>{task.completion_rule=rule.value;if(rule.value!=='manual'&&task.status==='done')task.status='todo';renderProjectTasks()};const milestone=document.createElement('select');milestone.setAttribute('aria-label','所属里程碑');const blank=text('option','未关联里程碑');blank.value='';milestone.append(blank);for(const item of projectMilestones){const option=text('option',item.title);option.value=item.milestone_id;milestone.append(option)}milestone.value=task.milestone_id||'';milestone.onchange=()=>task.milestone_id=milestone.value||null;const evidence=text('small','完成证据：'+(task.evidence_refs||[]).length+' 条');const remove=text('button','移除');remove.onclick=()=>{projectTasks=projectTasks.filter(item=>item.task_id!==task.task_id);renderProjectTasks()};row.append(title,type,status,due,assessment,rule,milestone,evidence,remove);box.append(row)}}
$('add-project-milestone').onclick=()=>{const title=$('project-milestone-title').value.trim();if(!title)return notice('请填写里程碑名称',true);projectMilestones.push({milestone_id:crypto.randomUUID(),title,status:'todo'});$('project-milestone-title').value='';renderProjectMilestones();renderProjectTasks()};
