function openCurrentProjectEditor(){if(!activeProjectRecord)return notice('请先创建并选择项目',true);const plan=savedPlans.find(item=>item.version_id===planVersion);const draftContent=plan?.content?.project_plan;const editable=draftContent?{...activeProjectRecord,content:draftContent}:activeProjectRecord;$('project-editor').open=true;editProject(editable)}
