function projectRefs(id){return [...new Set($(id).value.split(/[\n,，]+/).map(value=>value.trim()).filter(Boolean))]}
function editedProjectContent(){return {...(projectEdit?.content||{}),title:$('project-title').value.trim(),description:$('project-description').value.trim(),tasks:projectTasks,milestones:projectMilestones,evidence_refs:projectRefs('project-evidence-refs'),session_refs:projectRefs('project-session-refs'),source_refs:projectRefs('project-source-refs'),archived:projectEdit?.content.archived||false}}
function editablePlanForProjectArrangement(){
  const selected=savedPlans.find(plan=>plan.version_id===planVersion);
  if(selected&&['draft','confirmed'].includes(selected.status))return selected;
  return currentWorkspace?.drafts?.find(plan=>plan.status==='draft')
    ||currentWorkspace?.active
    ||savedPlans.find(plan=>['draft','confirmed'].includes(plan.status))
    ||null;
}
$('save-project').onclick=run(async()=>{if(!projectEdit||projectEdit.record_id!==activeProjectId)throw Error('当前项目尚未载入编辑器；请重新打开“编辑当前项目”后再保存。保存项目安排不会创建项目。');const title=$('project-title').value.trim();if(!title)throw Error('请填写项目名称');const content=editedProjectContent();if(currentWorkspace?.contract){const base=editablePlanForProjectArrangement();if(!base)throw Error('当前项目还没有可编辑的计划版本；请先建立目标并生成计划草案');const reason=$('plan-notes').value.trim()||'调整项目任务、截止日期或里程碑';notice('正在保存项目安排，并创建新的计划草案…');const revised=await api('/api/plans/'+encodeURIComponent(base.version_id)+'/modify',projectBody({learner_id:learner,content:editedPlanContent(base.content,content),reason}));$('project-editor').open=false;await restorePlanWorkspace();$('saved-plan').value=revised.version_id;restorePlanSelection();notice('项目安排已保存为未签署的新草案；当前已签署计划仍保持生效');return}notice('正在保存项目安排…');const result=await api('/api/learning/projects/'+learner,{record_id:projectEdit.record_id,expected_revision:projectEdit.revision,content});$('project-editor').open=false;await loadProjects();if(!result.content.archived)await activateProject(result.record_id,true);else await updateOverview();notice('项目安排已保存')});
