async function sharingRecord(){try{return await api('/api/learning/sharing/'+learner)}catch(error){if(error.message==='No explicit audience sharing record')return null;throw error}}
$('save-sharing').onclick=run(async()=>{const current=await sharingRecord();const audience=$('share-audience').value;const result=await api('/api/learning/sharing/'+learner,{audiences:audience==='none'?[]:audience==='both'?['teacher','parent']:[audience],expected_revision:current?.revision||0});notifyPrivacyChange('sharing');$('sharing-status').textContent='共享版本 '+result.revision+' · '+(result.content.audiences.map(a=>a==='teacher'?'教师':'家长').join('、')||'未共享');notice('共享选择已保存')});
async function restoreWorkspaceExtras(){projectEdit=null;projectTasks=[];for(const id of ['save-project','save-sharing','sidebar-new-project','sidebar-project-save'])$(id).disabled=false;await loadProjects();const record=await sharingRecord();const audiences=record?.content.audiences||[];$('share-audience').value=audiences.length===2?'both':audiences[0]||'none';$('sharing-status').textContent=record?'共享版本 '+record.revision+' · '+(audiences.map(a=>a==='teacher'?'教师':'家长').join('、')||'未共享'):'尚未保存共享对象';await updateOverview()}
async function loadCollaborationEvidence(){const [evidence,providers]=await Promise.all([api(projectUrl('/api/learning/evidence/'+learner)),api('/api/providers')]);const replaced=new Set(evidence.map(item=>item.supersedes).filter(Boolean));$('collaboration-evidence').replaceChildren();for(const item of evidence.filter(item=>!replaced.has(item.evidence_id))){const option=text('option',item.assessment_id+' · '+(labels[item.verdict_status]||item.verdict_status));option.value=item.evidence_id;option.title=item.evidence_id;$('collaboration-evidence').append(option)}$('collaboration-provider').replaceChildren();for(const provider of providers.providers){const option=text('option',provider.provider_id==='offline'?'离线固定模板':provider.provider_id+' · '+provider.model);option.value=provider.provider_id;$('collaboration-provider').append(option)}notice('有效证据与执行来源已刷新')}
$('refresh-collaboration-evidence').onclick=run(loadCollaborationEvidence);
function collaborationBody(){const evidence_ids=[...$('collaboration-evidence').selectedOptions].map(option=>option.value);if(!evidence_ids.length)throw Error('请选择至少一条当前有效证据');const max_tokens=Number($('collaboration-tokens').value);if(!Number.isInteger(max_tokens)||max_tokens<1||max_tokens>4000)throw Error('输出预算必须为 1–4000');return projectBody({evidence_ids,student_work:$('collaboration-work').value,learner_id:learner,provider_id:$('collaboration-provider').value,max_tokens,deadline_ms:3000})}
function candidateActionText(action){return action.params?.text||action.params?.stem||action.params?.question||'暂无可显示的候选文本'}
function appendCandidateReport(box,result){const report=result.report;const part=document.createElement('div');part.className='band';part.append(text('h3',({prompter:'提示者',skeptic:'怀疑者',reviewer:'评审者',teach_virtual_student:'虚拟学生'}[report.role]||report.role)),text('p',(result.execution_mode==='deterministic_demo'?'离线固定模板':'配置模型输出')+' · 待验证候选 · '+report.exit_status));for(const observation of report.observations||[])part.append(text('p',observation));if(report.misconception)part.append(text('p',report.misconception));if(report.rationale)part.append(text('p',report.rationale));for(const action of report.actions||[])part.append(text('p',candidateActionText(action)));part.append(text('p','未直接写入学习状态或签署计划。'),sourceDetails({report_id:result.report_id,evidence:report.evidence_refs||report.provenance?.evidence_refs,artifacts:report.artifact_refs,kc:report.kc_refs,provenance:result.provenance,source_refs:result.source_refs,reviews:report.reviews,actions:report.actions}));box.append(part)}
$('role-review').onclick=run(async()=>{const result=await api('/api/roles/'+$('collaboration-role').value+'/review',collaborationBody());$('collaboration-results').replaceChildren();appendCandidateReport($('collaboration-results'),result);notice('单角色候选建议已生成')});
$('roundtable-review').onclick=run(async()=>{const result=await api('/api/roundtable/review',{...collaborationBody(),roles:['prompter','skeptic','reviewer']});const box=$('collaboration-results');box.replaceChildren(text('p','三角色候选，未评估共识；需要后续验证。'));for(const report of result.reports)appendCandidateReport(box,report);notice('圆桌候选建议已生成')});
$('teach-student').onclick=run(async()=>{const lesson=$('teach-lesson').value.trim();if(!lesson)throw Error('请填写自己的讲解');const result=await api('/api/teach-student/lesson',{...collaborationBody(),lesson});$('teach-results').replaceChildren();appendCandidateReport($('teach-results'),result);notice('虚拟学生候选误区已生成，等待你的检查')});
$('load-strategies').onclick=run(async()=>{const result=await api('/api/strategies?kc_id='+encodeURIComponent($('target').value));const box=$('strategy-results');box.replaceChildren();if(!result.cards.length)box.append(text('p','当前知识点暂无策略卡'));for(const card of result.cards){const part=document.createElement('div');part.className='band';part.append(text('h3',card.purpose),text('p','策略 '+card.strategy_id+'@'+card.version+' · 待人工审阅'));const steps=document.createElement('ol');card.steps.forEach(step=>steps.append(text('li',step)));part.append(steps,text('p','自查：'+card.checks.join('；')),sourceDetails({kc:card.kc_refs,provenance:card.provenance,calibrated:card.calibrated}));box.append(part)}notice('策略候选卡已加载')});
$('search-knowledge').onclick=run(async()=>{const query=$('knowledge-query').value.trim();if(!query)throw Error('请填写检索问题');const result=await api('/api/knowledge/search?q='+encodeURIComponent(query)+'&kc_id='+encodeURIComponent($('target').value)+'&mode='+$('knowledge-mode').value);const box=$('knowledge-results');box.replaceChildren(text('p','引用候选，未经教学验证；向量为词特征，不是神经语义模型。'));if(!result.results.length)box.append(text('p','暂无匹配且有效的来源'));for(const source of result.results){const part=document.createElement('div');part.className='band';part.append(text('h3',source.source_id),text('p',source.text));const link=text('a','查看原文');link.href=source.source_url;link.target='_blank';link.rel='noopener';part.append(link,sourceDetails({version:source.source_version,chunk:source.chunk_id,citation:source.citation,kc:source.kc_refs}));box.append(part)}notice('知识引用候选已检索')});
$('new-session').onclick=run(async()=>{if(!activeProjectId)throw Error('请先创建并选择学习项目');clearStudyTask();const result=await api('/api/sessions',projectBody({learner_id:learner,session_type:'explore'}));sessionId=result.session_id;$('session-recovery-id').value=sessionId;sessionSubmission=null;$('chat').replaceChildren();addChat('桂子问津',result.reply);await loadProjectSessions();notice('自由探索会话已开始；不会自动完成计划任务')});
$('start-task-session').onclick=run(async()=>{if(!activeProjectId||!activeStudyTask)throw Error('请先从当前项目启动任务');const result=await api('/api/sessions',projectBody({learner_id:learner,session_type:'explore',task_id:activeStudyTask.task_id}));sessionId=result.session_id;$('session-recovery-id').value=sessionId;sessionSubmission=null;$('chat').replaceChildren();addChat('桂子问津',result.reply);await loadProjectSessions();notice('已开始关联当前项目任务的陪学会话')});
$('new-project-chat').onclick=()=>{show('study');$('new-session').click()};
$('restore-session').onclick=run(async()=>{const sid=$('session-recovery-id').value.trim();if(!sid)throw Error('请填写已保存的 Session ID');const result=await api(projectUrl('/api/sessions/'+encodeURIComponent(sid)));sessionId=result.session_id;sessionSubmission=null;activeStudyTask=(activeProjectRecord?.content.tasks||[]).find(task=>task.task_id===result.task_id)||null;renderStudyContext();$('session-recovery-id').value=sessionId;$('chat').replaceChildren();for(const message of result.messages||[])addChat(message.who,message.text);if(!result.messages?.length)$('chat').append(text('p','已恢复会话 · '+result.turn_count+' 轮'));notice(activeStudyTask?'已恢复当前项目任务的陪学会话':'已恢复自由探索会话，可以继续作答或求助')});
$('session-submit').onclick=run(async()=>{if(!sessionId)throw Error('请先开始会话');if(!$('session-answer').value.trim())throw Error('请填写会话作答');if(!sessionSubmission)sessionSubmission={answer:$('session-answer').value,attempt_id:crypto.randomUUID()};const result=await api(projectUrl('/api/sessions/'+sessionId+'/messages'),sessionSubmission);addChat('我的作答',sessionSubmission.answer);addChat('桂子问津',result.reply);notice('会话作答已保存')});
async function send(message){if(!sessionId)throw Error('请先开始会话');const result=await api(projectUrl('/api/sessions/'+sessionId+'/messages'),{text:message,attempt_id:crypto.randomUUID()});addChat('我',message);addChat('桂子问津',result.reply);if(result.denial)notice(result.denial.rule+' · '+(result.denial.reason||'规则裁决'),true);$('message').value=''}
async function loadProjectSessions(){const box=$('project-sessions');box.replaceChildren();if(!activeProjectId){box.append(text('p','请先创建并选择项目'));return}const result=await api('/api/learning/projects/'+encodeURIComponent(activeProjectId)+'/sessions');if(!result.sessions.length){box.append(text('p','当前项目暂无聊天'));return}for(const session of result.sessions){const task=(activeProjectRecord?.content.tasks||[]).find(item=>item.task_id===session.task_id);const button=text('button',(task?'任务聊天 · '+task.title:'自由聊天')+' · '+new Date(session.created_at).toLocaleDateString());button.title=session.session_id;button.onclick=()=>{$('session-recovery-id').value=session.session_id;show('study');$('restore-session').click()};box.append(button)}}
$('send').onclick=run(()=>send($('message').value));$('help').onclick=run(()=>send('我已经尝试过了，请给我一个提示'));
async function loadReviews(){if(activeProjectId){const synced=await api('/api/learning/reviews/'+learner+'/sync',projectBody({}));activeProjectRecord=synced.project||activeProjectRecord}const data=await api(projectUrl('/api/learning/reviews/'+learner));projectReviews=data.tasks||[];renderPlanDashboard(currentWorkspace,activeProjectRecord,projectReviews);$('review-list').replaceChildren();if(!data.tasks.length){$('review-list').textContent='暂无到期复习';return}for(const task of data.tasks){const row=document.createElement('div');row.className='band';row.append(text('h3',task.kc_id),text('p','到期：'+new Date(task.due_at).toLocaleString()+' · 遗忘风险 '+Math.round(task.forgetting_risk*100)+'%'));const btn=text('button','开始复习');btn.onclick=()=>{const a=assets.find(a=>a.kind==='delayed'&&a.kc_refs.some(k=>k.asset_id===task.kc_id));if(!a){notice('当前知识点缺少复习资产',true);return}if(![...$('assessment').options].some(o=>o.value===a.ref.asset_id)){const o=text('option',a.ref.asset_id+' · 到期复习');o.value=a.ref.asset_id;$('assessment').append(o)}$('assessment').value=a.ref.asset_id;chooseTask();review=task;$('assisted').checked=false;show('study');notice('到期复习已就绪')};row.append(btn);$('review-list').append(row)}}
$('refresh-reviews').onclick=run(loadReviews);
async function loadMetrics(){const result=await api(projectUrl('/api/learning/metrics/'+learner+'?kc_id='+encodeURIComponent($('target').value)+'&post_kind='+$('metric-kind').value));const el=$('metric-result');el.replaceChildren();if(result.status!=='comparable'){el.append(text('p',result.status==='incomparable'?'当前样本不可比较':'暂无可比较数据'),text('p','前测样本 '+result.pre_count+' · 对比样本 '+result.post_count));return}const band=document.createElement('div');band.className='metric';[['前测',result.pre_mean],['对比测',result.post_mean],['增量',result.gain]].forEach(([name,n])=>{const d=document.createElement('div');d.append(text('span',name),text('strong',Math.round(n*100)+'%'));band.append(d)});el.append(band,text('p','样本：'+result.pre_count+' / '+result.post_count+' · 描述性结果，课程资产尚未校准'));}
$('metric-kind').onchange=run(loadMetrics);
async function loadEvidence(){const [state,evidences]=await Promise.all([api(projectUrl('/api/learning/state/'+learner)),api(projectUrl('/api/learning/evidence/'+learner))]);$('state-list').replaceChildren();if(!state.mastery.length)$('state-list').append(text('p','暂无学习状态'));state.mastery.forEach(m=>{const r=state.retention.find(r=>r.kc_id===m.kc_id);$('state-list').append(text('p',m.kc_id+' · 掌握估计 '+Math.round(m.p_mastery*100)+'% · 有效证据 '+m.effective_evidence_count+' · 保持版本 '+(r?.state_version||0)))});$('evidence-list').replaceChildren();if(!evidences.length)$('evidence-list').append(text('p','暂无学习证据'));[...evidences].reverse().forEach(e=>{const detail=document.createElement('details');detail.append(text('summary',e.assessment_id+' · '+(labels[e.verdict_status]||e.verdict_status)+' · '+new Date(e.occurred_at).toLocaleString()),text('pre',JSON.stringify(e,null,2)));$('evidence-list').append(detail)});await loadMetrics();await loadGrowth()}
$('refresh-evidence').onclick=run(loadEvidence);
$('refresh-development').onclick=run(async()=>{const selected=$('development-split').value;if(!selected)throw Error('请选择前后窗口的分界时间');const split=new Date(selected);if(!Number.isFinite(split.getTime())||split>=new Date())throw Error('分界时间必须早于当前时间');const result=await api(projectUrl('/api/learning/metrics/development/'+learner+'?split_at='+encodeURIComponent(split.toISOString())));const box=$('development-result');box.replaceChildren();const cognition=result.cognitive;box.append(text('h3','认知层级窗口'),text('p',cognition.status==='comparable'?'已取得可比较的认知层级证据':cognition.status==='incomparable'?'认知层级证据不可比较':'认知层级证据不足'),text('p','分界前 '+cognition.before_count+' 条 · 分界后 '+cognition.after_count+' 条'));if(cognition.status==='comparable')box.append(sourceDetails({before_distribution:cognition.before_distribution,after_distribution:cognition.after_distribution,rubric_version:cognition.rubric_version}));const autonomy=result.autonomy;box.append(text('h3','自主性行为'),text('p',autonomy.status==='insufficient_data'?'暂无行为数据':'独立尝试 '+autonomy.independent_attempt_count+' · 独立完成 '+autonomy.independent_success_count+' · 支架作答 '+autonomy.assisted_attempt_count),text('p','主动求助 '+autonomy.help_request_count+' · 自我检查 '+autonomy.self_check_count+' · 反思 '+autonomy.reflection_count+' · 修订 '+autonomy.revision_count),text('p','窗口与行为描述，不作因果效果结论或排名。'),sourceDetails(result.source_refs));notice('发展证据已更新')});
$('rebuild-memory').onclick=run(async()=>{const memory=await api(projectUrl('/api/learning/memory/'+learner+'/rebuild'),{});const box=$('memory-result');box.replaceChildren(text('p','重建时间：'+new Date(memory.as_of).toLocaleString()),text('p','事实来源：'+memory.l1.evidence_refs.length+' 条学习证据、'+memory.l1.event_refs.length+' 条交互事件'));for(const session of memory.l2){const detail=document.createElement('details');detail.append(text('summary','会话 '+session.session_id+' · '+session.evidence_refs.length+' 条证据'),text('p','验证记录：'+Object.entries(session.verdict_counts).map(([key,value])=>(labels[key]||key)+' '+value).join('、')),sourceDetails({evidence:session.evidence_refs,events:session.event_refs}));box.append(detail)}box.append(text('p','长期描述只引用状态版本与行为来源。'),sourceDetails({l1:memory.l1,l3:memory.l3,view_id:memory.view_id}));notice('学习记忆已重建')});
run(async()=>{const config=await api('/api/learning/config');learner=config.learner_id;$('logout').hidden=!config.local_auth_enabled;$('identity').textContent='本地学习者';$('identity').title=learner;const data=await api('/api/learning/assets');assets=data.assessments;data.knowledge.forEach(k=>{const o=text('option',k.title);o.value=k.ref.asset_id;$('target').append(o)});$('target').value=data.knowledge.some(k=>k.ref.asset_id==='MATH.G7.EQ.SOLVE')?'MATH.G7.EQ.SOLVE':data.knowledge[0]?.ref.asset_id||'';changeTarget();if(!await loadConsent())show('settings');else{await restoreWorkspaceExtras();changeTarget();await restorePlanWorkspace();await Promise.all([loadProjectSessions(),loadCollaborationEvidence()])}})()
